"""Torch fallback for GELU residual kernel."""


import torch
import torch.nn.functional as F


def gelu_residual_torch_into(
    *, out: torch.Tensor, inp: torch.Tensor, interleaved: bool = False
) -> None:
    hidden = int(out.shape[-1])
    if interleaved:
        # [gate[0:8], up[0:8], gate[8:16], up[8:16], ...] -> gate/up halves.
        pair = inp.reshape(*inp.shape[:-1], hidden // 8, 2, 8)
        x = pair[..., 0, :].reshape(*inp.shape[:-1], hidden)
        y = pair[..., 1, :].reshape(*inp.shape[:-1], hidden)
    else:
        x = inp[..., :hidden]
        y = inp[..., hidden:]
    out.copy_(F.gelu(x, approximate="none") * (y + 1))


__all__ = ["gelu_residual_torch_into"]
